// ReverseCandidate 候補1件(性格クラス × 持ち物。ADR-0010 §R3)
type ReverseCandidate struct {
	// AbilityId この候補の計算に使った相手の特性(ADR-0126・ADR-0214)。種族は必ず1件以上の特性を持つため
	// 常に入る。
	AbilityId string `json:"abilityId"`

	// AbilityIds この候補と結果が完全に同じになる特性の ID(abilityId が先頭。渡した/解決した順)。
	AbilityIds []string `json:"abilityIds"`

	// Exact mismatch == 0(全観測を説明できる)
	Exact bool `json:"exact"`

	// ItemId 持ち物(持ち物なしは null)
	ItemId *string `json:"itemId"`

	// MaxPercent ranges 全体での想定ダメージ幅の上限(表示%。小数第1位・四捨五入。CalcResult.maxPercent と同じ意味)
	MaxPercent float64 `json:"maxPercent"`

	// MinPercent ranges 全体での想定ダメージ幅の下限(表示%。小数第1位・切り捨て。CalcResult.minPercent と同じ意味)
	MinPercent float64 `json:"minPercent"`

	// Mismatch 観測とのずれ(0.1% 単位の整数。0 は完全に説明できる)
	Mismatch int `json:"mismatch"`

	// Nature 性格補正の構造値。plus が +10%、minus が -10% を受ける能力。無補正は両方 null。
	// HP を指すことはない。
	Nature NatureModifier `json:"nature"`

	// NatureClass 関連ステータスに対する性格補正のクラス(neutral=無補正 / plus=関連ステータス +10%)。下降補正は探索しない
	NatureClass NatureClass `json:"natureClass"`

	// NatureId nature と (plus, minus) が一致するマスタの性格 ID(BulkDefender.natureId と同じ規則)。
	// 無補正は、マスタの無補正性格を ID の昇順で並べた最初のもの。該当なしは null。
	NatureId *string `json:"natureId"`

	// Ranges 観測を説明できる SP の集合(昇順・互いに素・隣接しない極大連続区間)。説明できなければ距離最小の SP
	Ranges []SPRange `json:"ranges"`

	// SpCount ranges に含まれる SP の数
	SpCount int `json:"spCount"`

	// Support ranges の各 SP で各観測を説明できるロールの延べ数
	Support int `json:"support"`

	// Unsupported この候補の計算に付いた「未対応」の印(ADR-0123)。SP によらず同じ(技・場・既知側は候補間で共通)。
	// 印なしは空配列。
	Unsupported []UnsupportedMark `json:"unsupported"`
}

// ReverseRequest defines model for ReverseRequest.
type ReverseRequest struct {
	Field *FieldState `json:"field,omitempty"`

	// Format 対戦形式。計算(/api/calc・/api/calc/bulk・/api/calc/reverse)では double のとき次を掛ける(issue 232 案B のダブル分・ADR-0222)。
	// - 防御側の壁(リフレクター・ひかりのかべ・オーロラベール): ×2732/4096(single は ×1/2)。急所は壁を無視する
	// - 全体技(技の対象が相手全体・自分以外全体): 基礎ダメージに ×3072/4096(天候・急所より前)。
	//   1対1の計算なので、全体技は常に2体以上に当たる前提で掛ける。味方の効果(てだすけ等)は扱わない
	// 技の対象をマスタが持たない間(issue 288)は、double の攻撃技に UnsupportedMark
	// (target=move・reason=move_target_unknown)を付け、全体技の補正は掛けない(壁は掛ける)。
	// double は計算に反映するので形式の印は付けない。engine に未知の形式が届いたときだけ安全側で
	// target format・reason unsupported_effect の印が付く(ADR-0160・ADR-0222 §5)。
	Format Format `json:"format"`

	// ItemCandidates 相手の持ち物の候補(ID)。null 要素は「持ち物なし」。省略・空配列は [null] と同じ。
	// unknownSpeciesKey がメガシンカ後の種族のとき、requiredItemId 以外の持ち物を含めると 400 `invalid_input`(ADR-0200 §4)。
	// 65 件以上、または同じ値(null どうしを含む)の重複は 400 `invalid_input`(ADR-0208)。
	ItemCandidates *[]*string `json:"itemCandidates,omitempty"`

	// Known 既知の側(自分)の個体。side=defender なら自分=攻撃側、side=attacker なら自分=防御側。
	// Individual に moveId は無い(技は moveId で指定する)。
	Known Individual `json:"known"`

	// MaxCandidates 返す候補数の上限。0 は「許可された入力から生まれる候補の全件」(特性の候補分岐〈ADR-0126・
	// ADR-0214〉により最大 2 性格クラス × 3 特性グループ × 64 itemCandidates = 384 件まで増えうる。
	// 特性が効かない技では従来どおり最大 128 件)。指定できる値自体は 1..128(この上限は変えていない。
	// 返る件数をこの値で切り詰めるだけで、384 件から絞り込みたいときに使う)。負の値と 129 以上は
	// 400 `invalid_input`。
	MaxCandidates *int `json:"maxCandidates,omitempty"`

	// MoveId 観測したときの技(side=defender なら自分の技、attacker なら相手の技)
	MoveId string `json:"moveId"`

	// Observations 同じ技・同じ場・同じ既知側に対する別々の1発。0 件は 400 `no_observation`、
	// 17 件以上は 400 `invalid_input`(ADR-0208)。同じ内容の観測を繰り返してよい
	// (絞り込みに寄与しないだけで矛盾しない)ので `uniqueItems` は付けない。
	Observations []Observation `json:"observations"`
	Options      *CalcOptions  `json:"options,omitempty"`

	// Side どちら側の調整を逆算するか(defender=与ダメ観測 / attacker=被ダメ観測)
	Side ReverseSide `json:"side"`

	// UnknownAbilityId 相手の特性を1つに固定する(issue 272。ADR-0126・ADR-0214)。省略時は相手の種族が持つ特性
	// (最大3件。BulkCalcRequest.defenderOverride.abilityId と同じ既定)をすべて候補にする。
	// 指定した特性をその種族が持たない場合は 400 `invalid_input`、マスタに無い ID は
	// 400 `unknown_ability`。
	UnknownAbilityId *string `json:"unknownAbilityId,omitempty"`

	// UnknownSpeciesKey 逆算する相手の種族。SP・性格・持ち物は探索対象なので渡さない
	UnknownSpeciesKey SpeciesKey `json:"unknownSpeciesKey"`
}

